# UI catalog: key -> (en, pt-BR, es). Placeholders use {name}.
UI = {}


def add(entries):
    for k, v in entries.items():
        assert k not in UI, f"duplicate key {k}"
        assert len(v) == 3, k
        UI[k] = v


